from dataclasses import dataclass, field
from typing import List


@dataclass
class FeatureSpec:
    feature_id: str
    feature_name: str
    domain: str
    scale: str
    timescale: str
    observability: str
    reversibility: str
    emergence_class: str
    mechanism: str
    state_space: str
    measurement: str
    upstream_causes: List[str] = field(default_factory=list)
    downstream_effects: List[str] = field(default_factory=list)
    interaction_rules: List[str] = field(default_factory=list)
    pathological_extremes: List[str] = field(default_factory=list)
    real_world_validation: List[str] = field(default_factory=list)
    implementation_notes: List[str] = field(default_factory=list)
    tags: List[str] = field(default_factory=list)


EXTENDED_FEATURES: List[FeatureSpec] = []


